using Microsoft.EntityFrameworkCore;
using PeopleHub.Infrastructure.Persistence;
using PeopleHub.Application.Services;
using PeopleHub.Domain.Entities;
namespace PeopleHub.Tests;
public class EmployeeLifecycleTests
{
 class User(int employee=1,bool hr=true):ICurrentUser{public string Email=>"lifecycle@example.local";public int? EmployeeId=>employee;public int UserId=>1;public bool IsAuthenticated=>true;public bool IsInRole(string r)=>hr;public bool Can(string p)=>hr;}
 static async Task<AppDbContext> Db(){var d=new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseSqlite("Data Source=:memory:").Options);await d.Database.OpenConnectionAsync();await d.Database.MigrateAsync();await SeedData.InitializeAsync(d,"Admin123!","Demo123!",new DateTime(2026,11,24));return d;}
 static EmployeeLifecycle S(AppDbContext d,User? u=null){u??=new();var c=new AppClock(TimeProvider.System);var a=new AuditService(d,u,c);return new(d,u,new AccessScope(d,u),c,a,new NotificationService(d,u,c));}
 [Fact]public async Task DependentIsPrivateAndRequiresHrToChange(){await using var d=await Db();await S(d).AddDependentAsync(6,"Fictional child","Child",new(2020,1,1));Assert.Single((await S(d,new(6,false)).GetAsync(6)).Dependents);await Assert.ThrowsAsync<DomainException>(()=>S(d,new(6,false)).AddDependentAsync(6,"Other","Child",null));await Assert.ThrowsAsync<DomainException>(()=>S(d,new(7,false)).GetAsync(6));await S(d).RemoveDependentAsync((await d.Set<EmployeeDependent>().SingleAsync()).Id,"Test correction");Assert.Empty(await d.Set<EmployeeDependent>().ToListAsync());}
 [Fact]public async Task AssignedTaskRequiresCompletionEvidenceAndCanOnlyCompleteOnce(){await using var d=await Db();await S(d).AddTaskAsync(6,"Clearance","Return fictional laptop",7,new(2026,12,1));var t=await d.Set<LifecycleTask>().SingleAsync();await Assert.ThrowsAsync<DomainException>(()=>S(d,new(8,false)).CompleteTaskAsync(t.Id,"Done"));await Assert.ThrowsAsync<DomainException>(()=>S(d,new(7,false)).CompleteTaskAsync(t.Id,""));await S(d,new(7,false)).CompleteTaskAsync(t.Id,"Receipt recorded");Assert.Equal("Complete",t.Status);Assert.NotNull(t.CompletedAt);await Assert.ThrowsAsync<DomainException>(()=>S(d).CompleteTaskAsync(t.Id,"Again"));Assert.Equal(EmployeeStatus.Active,(await d.Set<Employee>().FindAsync(6))!.Status);}
 [Fact]public async Task ProbationConfirmationDoesNotChangeSalaryAndIsFinal(){await using var d=await Db();var e=(await d.Set<Employee>().FindAsync(6))!;var salary=e.BasicSalary;await S(d).SetProbationAsync(6,new(2026,12,1),"Recorded offer term");await S(d).DecideProbationAsync(6,"Confirmed","Review complete");Assert.Equal(salary,e.BasicSalary);Assert.Equal(EmployeeStatus.Active,e.Status);await Assert.ThrowsAsync<DomainException>(()=>S(d).DecideProbationAsync(6,"NotConfirmed","Again"));}
 [Fact]public async Task TypedCustomFieldsValidateInputAndStayHrOnly(){await using var d=await Db();await S(d).AddFieldAsync("Fictional allocation","تخصيص وهمي","Number");var f=await d.Set<HrFieldDefinition>().SingleAsync();await Assert.ThrowsAsync<DomainException>(()=>S(d).SetFieldAsync(6,f.Id,"text"));await S(d).SetFieldAsync(6,f.Id,"12.5");Assert.Equal("12.5",(await S(d).GetAsync(6)).Values.Single().Value);Assert.Empty((await S(d,new(6,false)).GetAsync(6)).Values);await Assert.ThrowsAsync<DomainException>(()=>S(d,new(6,false)).SetFieldAsync(6,f.Id,"15"));}
 [Fact]public async Task InvalidTaskNeverPersists(){await using var d=await Db();await Assert.ThrowsAsync<DomainException>(()=>S(d).AddTaskAsync(6,"Invalid","Task",7,new(2026,12,1)));Assert.Empty(await d.Set<LifecycleTask>().ToListAsync());}
 [Fact]public async Task AssignedTaskInboxExposesOnlyAssignedWorkWithoutOtherPrivateProfile(){await using var d=await Db();await S(d).AddDependentAsync(6,"Private dependent","Child",null);await S(d).AddTaskAsync(6,"Clearance","Return fictional asset",7,new(2026,12,1));await S(d).AddTaskAsync(8,"Onboarding","Other task",9,new(2026,12,1));var own=await S(d,new(7,false)).GetAsync(7);var task=Assert.Single(own.AssignedTasks);Assert.Equal(6,task.EmployeeId);Assert.Empty(own.Dependents);await Assert.ThrowsAsync<DomainException>(()=>S(d,new(7,false)).GetAsync(6));await S(d,new(7,false)).CompleteTaskAsync(task.Id,"Receipt checked");Assert.Empty((await S(d,new(7,false)).GetAsync(7)).AssignedTasks);}
 class ScopedManager:ICurrentUser{public string Email=>"manager@example.local";public int? EmployeeId=>1;public int UserId=>1;public bool IsAuthenticated=>true;public bool IsInRole(string r)=>false;public bool Can(string p)=>p==Perm.ScopeCompany;}
 [Fact]public async Task CompanyScopeAloneDoesNotRevealPrivateTasksOrProbationReason(){await using var d=await Db();await S(d).AddTaskAsync(6,"Offboarding","Private case checklist",7,new(2026,12,1));await S(d).AddTaskAsync(6,"Clearance","Assigned equipment receipt",1,new(2026,12,1));await S(d).SetProbationAsync(6,new(2026,12,1),"Private review reason");var u=new ScopedManager();var c=new AppClock(TimeProvider.System);var a=new AuditService(d,u,c);var v=await new EmployeeLifecycle(d,u,new AccessScope(d,u),c,a,new NotificationService(d,u,c)).GetAsync(6);Assert.Single(v.Tasks);Assert.Equal("Assigned equipment receipt",v.Tasks[0].Title);Assert.Null(v.Probation);var own=await S(d,new(6,false)).GetAsync(6);Assert.Equal(2,own.Tasks.Count);Assert.NotNull(own.Probation);}

}
